-- Registra os encaminhamentos da reunião geral de 06/11/2026 e adota os nomes oficiais dos setores.
begin;

update public.areas set name='Gestão' where slug='gestao';
update public.areas set name='Financeiro' where slug='financeiro';
update public.areas set name='Marketing' where slug='marketing';
update public.areas set name='Mecânica Naval' where slug='mecanica-naval';
update public.areas set name='Elétrica' where slug='eletrica';
update public.areas set name='Telemetria' where slug='telemetria';
update public.areas set is_active=false where slug='projetos-historico';

-- Permite cadastrar atividades pontuais sem prazo definido.
alter table public.activities drop constraint if exists activities_type_dates;
alter table public.activities add constraint activities_type_dates check (
  (start_date is null or due_date is null or due_date >= start_date)
);

with seed as (
  select * from jsonb_to_recordset('[{"area_slug":"eletrica","name":"Avaliar condições das baterias","description":"Verificar as condições das baterias durante a revisão do sistema elétrico.","activity_type":"pontual","frequency":"","execution_condition":"","expected_deliverable":"Condições das baterias avaliadas"},{"area_slug":"eletrica","name":"Avaliar necessidade de bateria adicional","description":"Analisar a necessidade de aquisição de bateria adicional após a realização dos testes da instalação e das baterias.","activity_type":"pontual","frequency":"","execution_condition":"","expected_deliverable":"Necessidade de bateria adicional avaliada"},{"area_slug":"eletrica","name":"Elaborar novo esquema elétrico da embarcação","description":"Revisar e reorganizar o sistema elétrico da embarcação por meio da elaboração de um novo esquema e da verificação de conexões e componentes.","activity_type":"pontual","frequency":"","execution_condition":"","expected_deliverable":"Novo esquema elétrico elaborado"},{"area_slug":"eletrica","name":"Planejar instalação e integração do novo motor","description":"Planejar as etapas de montagem e integração elétrica do novo motor à embarcação.","activity_type":"pontual","frequency":"","execution_condition":"","expected_deliverable":"Etapas de instalação e integração planejadas"},{"area_slug":"eletrica","name":"Realizar testes de funcionamento do novo motor","description":"Executar e registrar os testes de funcionamento do novo motor após sua instalação e integração elétrica.","activity_type":"pontual","frequency":"","execution_condition":"","expected_deliverable":"Testes de funcionamento registrados"},{"area_slug":"eletrica","name":"Retirar painéis e cobertura elétrica","description":"Planejar e executar a retirada dos painéis e da cobertura elétrica para permitir a revisão e os testes da instalação.","activity_type":"pontual","frequency":"","execution_condition":"","expected_deliverable":"Painéis e cobertura retirados"},{"area_slug":"eletrica","name":"Testar instalação elétrica fora da embarcação","description":"Preparar e testar a instalação elétrica fora da embarcação, verificando conexões e componentes.","activity_type":"pontual","frequency":"","execution_condition":"","expected_deliverable":"Testes da instalação registrados"},{"area_slug":"financeiro","name":"Desenvolver política de precificação e margem de contribuição","description":"Definir critérios para calcular custos, preços de venda e margem de contribuição dos produtos oficiais.","activity_type":"pontual","frequency":"","execution_condition":"","expected_deliverable":"Critérios de precificação definidos"},{"area_slug":"financeiro","name":"Elaborar orçamento anual da equipe","description":"Consolidar previsão de receitas e despesas para apoiar o planejamento financeiro da equipe.","activity_type":"pontual","frequency":"","execution_condition":"","expected_deliverable":"Orçamento anual elaborado"},{"area_slug":"financeiro","name":"Estruturar controle de estoque, vendas e receitas","description":"Organizar o registro de estoque, pedidos, vendas e receitas provenientes dos produtos oficiais.","activity_type":"pontual","frequency":"","execution_condition":"","expected_deliverable":"Controle de estoque e vendas estruturado"},{"area_slug":"financeiro","name":"Estruturar linha de produtos oficiais SolMar Celeris","description":"Definir a linha inicial de produtos oficiais, considerando as iniciativas de camisas e chaveiros 3D mencionadas na reunião.","activity_type":"pontual","frequency":"","execution_condition":"","expected_deliverable":"Linha inicial de produtos estruturada"},{"area_slug":"financeiro","name":"Estruturar plano de captação de recursos","description":"Organizar a estratégia de captação combinando editais, patrocínios e parcerias, evitando dependência de uma única fonte.","activity_type":"pontual","frequency":"","execution_condition":"","expected_deliverable":"Estratégia de captação estruturada"},{"area_slug":"financeiro","name":"Identificar e verificar edital de fomento da FAPERJ","description":"Identificar o edital mencionado na reunião e verificar sua disponibilidade, condições e requisitos.","activity_type":"pontual","frequency":"","execution_condition":"","expected_deliverable":"Edital identificado e condições verificadas"},{"area_slug":"financeiro","name":"Levantar custos logísticos das competições","description":"Levantar despesas de deslocamento, alimentação, diárias e demais custos logísticos de participação em competições.","activity_type":"pontual","frequency":"","execution_condition":"","expected_deliverable":"Levantamento de custos logísticos"},{"area_slug":"financeiro","name":"Mapear empresas e instituições parceiras","description":"Identificar possíveis parceiros institucionais, comerciais e técnicos para apoiar as atividades da equipe.","activity_type":"pontual","frequency":"","execution_condition":"","expected_deliverable":"Mapeamento de parceiros"},{"area_slug":"financeiro","name":"Planejar produção e venda de camisas","description":"Planejar produção, custos e comercialização de camisas da equipe.","activity_type":"pontual","frequency":"","execution_condition":"","expected_deliverable":"Plano de produção e venda de camisas"},{"area_slug":"financeiro","name":"Planejar produção e venda de chaveiros 3D","description":"Planejar produção e comercialização de chaveiros confeccionados em impressora 3D.","activity_type":"pontual","frequency":"","execution_condition":"","expected_deliverable":"Plano de produção e venda de chaveiros"},{"area_slug":"financeiro","name":"Plano de Negócios do SolMar Celeris","description":"Marco futuro para estruturar um modelo de negócios e sustentabilidade econômica inspirado em agremiações esportivas. A elaboração não faz parte deste cadastro inicial.","activity_type":"marco","frequency":"","execution_condition":"","expected_deliverable":"Plano de Negócios elaborado e validado"},{"area_slug":"financeiro","name":"Prospectar potenciais patrocinadores","description":"Identificar e iniciar contato com empresas e potenciais patrocinadores e apoiadores.","activity_type":"rotina","frequency":"Semanal","execution_condition":"","expected_deliverable":"Lista de potenciais patrocinadores atualizada"},{"area_slug":"gestao","name":"Acompanhar entregas e responsabilidades","description":"Acompanhar o andamento das atividades e entregas, buscando ampliar a autonomia e evitar concentração de tarefas.","activity_type":"rotina","frequency":"Semanal","execution_condition":"","expected_deliverable":"Acompanhamento semanal atualizado"},{"area_slug":"gestao","name":"Atualizar manual de funções","description":"Consolidar as atribuições, responsabilidades e relações entre as áreas da equipe.","activity_type":"pontual","frequency":"","execution_condition":"","expected_deliverable":"Manual de funções atualizado"},{"area_slug":"gestao","name":"Confirmar composição dos novos pilotos","description":"Confirmar a composição dos novos pilotos e as funções de cada integrante; Vitor foi indicado como confirmado e Igor permanecia em avaliação na ata.","activity_type":"pontual","frequency":"","execution_condition":"","expected_deliverable":"Composição e funções dos pilotos confirmadas"},{"area_slug":"gestao","name":"Consolidar e validar o organograma","description":"Conduzir, no âmbito da Coordenação Geral, a consolidação e validação da estrutura organizacional apresentada na reunião.","activity_type":"pontual","frequency":"","execution_condition":"","expected_deliverable":"Organograma consolidado e validado"},{"area_slug":"gestao","name":"Definir funções de apoio durante as competições","description":"Detalhar as funções de apoio durante as competições, incluindo acompanhamento de voltas, tempos, percurso e observações técnicas.","activity_type":"pontual","frequency":"","execution_condition":"","expected_deliverable":"Distribuição de funções de apoio definida"},{"area_slug":"gestao","name":"Desenvolver método de acompanhamento da participação","description":"Definir forma de acompanhamento da participação dos integrantes, sem transformar o índice de 90% a 95% citado na reunião em regra aprovada.","activity_type":"pontual","frequency":"","execution_condition":"","expected_deliverable":"Método de acompanhamento definido"},{"area_slug":"gestao","name":"Elaborar PDIs dos integrantes","description":"Relacionar responsabilidades, competências a desenvolver, ferramentas e conhecimentos técnicos necessários às atividades de cada integrante.","activity_type":"pontual","frequency":"","execution_condition":"","expected_deliverable":"PDIs individuais elaborados"},{"area_slug":"gestao","name":"Elaborar proposta de manual de conduta","description":"Preparar proposta com orientações sobre compromissos, responsabilidades e possíveis medidas em casos de descumprimento, para posterior discussão e aprovação.","activity_type":"pontual","frequency":"","execution_condition":"","expected_deliverable":"Proposta de manual de conduta"},{"area_slug":"gestao","name":"Estruturar planejamento semanal","description":"Organizar o planejamento semanal das atividades da equipe.","activity_type":"rotina","frequency":"Semanal","execution_condition":"","expected_deliverable":"Planejamento semanal registrado"},{"area_slug":"gestao","name":"Levantar necessidades de capacitação por integrante","description":"Identificar competências e conhecimentos a desenvolver conforme as atividades atribuídas a cada integrante.","activity_type":"pontual","frequency":"","execution_condition":"","expected_deliverable":"Levantamento de necessidades de capacitação"},{"area_slug":"gestao","name":"Organizar curso de formação de pilotos","description":"Organizar formação com conteúdo teórico e prático, atividade em embarcação e avaliação dos participantes.","activity_type":"pontual","frequency":"","execution_condition":"","expected_deliverable":"Curso de formação organizado"},{"area_slug":"gestao","name":"Planejar implantação progressiva do Team Celeris","description":"Planejar a incorporação progressiva do Team Celeris como ambiente central de comunicação, arquivos, atividades e eventos.","activity_type":"pontual","frequency":"","execution_condition":"","expected_deliverable":"Plano de implantação progressiva definido"},{"area_slug":"marketing","name":"Desenvolver estratégias de visibilidade para patrocinadores","description":"Planejar formas de exposição e reconhecimento das marcas apoiadoras nos canais e materiais da equipe.","activity_type":"pontual","frequency":"","execution_condition":"","expected_deliverable":"Estratégias de visibilidade definidas"},{"area_slug":"marketing","name":"Elaborar estratégia de comunicação institucional","description":"Estruturar estratégias de comunicação e divulgação institucional da equipe.","activity_type":"pontual","frequency":"","execution_condition":"","expected_deliverable":"Estratégia de comunicação definida"},{"area_slug":"marketing","name":"Estruturar calendário de divulgação","description":"Organizar calendário de conteúdos e ações de divulgação da equipe.","activity_type":"pontual","frequency":"","execution_condition":"","expected_deliverable":"Calendário de divulgação estruturado"},{"area_slug":"marketing","name":"Realizar cobertura das competições e atividades da equipe","description":"Acompanhar e registrar atividades e competições para divulgação nos canais da equipe.","activity_type":"condicional","frequency":"","execution_condition":"Durante competições e atividades da equipe","expected_deliverable":"Registros e materiais de cobertura produzidos"},{"area_slug":"mecanica-naval","name":"Avaliar arredondamento da parte frontal do casco","description":"Avaliar tecnicamente a possibilidade de arredondamento da parte frontal do casco antes de qualquer execução.","activity_type":"pontual","frequency":"","execution_condition":"","expected_deliverable":"Avaliação técnica registrada"},{"area_slug":"mecanica-naval","name":"Avaliar tecnicamente a retirada do estabilizador dianteiro","description":"Avaliar os efeitos da possível retirada do estabilizador dianteiro, considerando o possível aumento de arrasto observado na reunião. Nenhuma alteração deve ser executada antes da avaliação.","activity_type":"pontual","frequency":"","execution_condition":"","expected_deliverable":"Avaliação técnica registrada"},{"area_slug":"mecanica-naval","name":"Executar manutenção da carretinha","description":"Executar a intervenção estrutural prevista, incluindo levantamento da estrutura, reforço de pontos vulneráveis, remoção de ferrugem e tratamento da superfície.","activity_type":"pontual","frequency":"","execution_condition":"","expected_deliverable":"Manutenção da carretinha concluída"},{"area_slug":"mecanica-naval","name":"Organizar visita técnica à oficina do Gaúcho","description":"Alinhar data, participantes, transporte e possibilidade de atividade prática de compartilhamento de conhecimentos na oficina.","activity_type":"pontual","frequency":"","execution_condition":"","expected_deliverable":"Visita técnica organizada"},{"area_slug":"mecanica-naval","name":"Planejar manutenção estrutural da carretinha","description":"Planejar a manutenção da carretinha, definindo responsáveis, materiais, custos e período de execução.","activity_type":"pontual","frequency":"","execution_condition":"","expected_deliverable":"Plano de manutenção definido"},{"area_slug":"telemetria","name":"Definir protocolo de coleta de dados durante competições","description":"Definir integrantes e procedimentos para registrar dados da embarcação e das equipes concorrentes, reduzindo divergências com o sistema oficial.","activity_type":"pontual","frequency":"","execution_condition":"","expected_deliverable":"Protocolo de coleta definido"},{"area_slug":"telemetria","name":"Estruturar registro de voltas e tempos","description":"Estruturar a coleta e o registro de dados como número de voltas, tempos e condições do percurso durante as competições.","activity_type":"pontual","frequency":"","execution_condition":"","expected_deliverable":"Estrutura de registro de dados definida"},{"area_slug":"telemetria","name":"Integrar dados de telemetria à avaliação de desempenho","description":"Organizar a utilização dos dados coletados para acompanhar e avaliar o desempenho da embarcação e apoiar melhorias.","activity_type":"pontual","frequency":"","execution_condition":"","expected_deliverable":"Dados integrados à avaliação de desempenho"}]'::jsonb)
  as x(area_slug text,name text,description text,activity_type public.activity_type,frequency text,execution_condition text,expected_deliverable text)
)
insert into public.activities (
  area_id,name,description,activity_type,frequency,execution_condition,
  responsible_name,start_date,due_date,expected_deliverable,notes,priority,flow_status
)
select
  a.id,s.name,s.description,s.activity_type,
  coalesce(s.frequency,''),coalesce(s.execution_condition,''),
  'A definir',null,null,s.expected_deliverable,'','medium','backlog'
from seed s
join public.areas a on a.slug=s.area_slug and a.is_active
where not exists (
  select 1 from public.activities old
  where old.area_id=a.id and lower(old.name)=lower(s.name) and old.archived_at is null
);

commit;
